          focus
        </button>
      </p>
      <ScreenshotArea>
        <Checkbox checked={checked} onChange={event => setChecked(event.detail.checked)}>
          Checkbox label
        </Checkbox>
      </ScreenshotArea>
    </article>
  );
}

